import { normalizeVec3 } from './vec';
import type { BoxZone } from './zones';

/** Bridges authored hole data to the runtime obstacle, pad and zone implementations. */

const DOWN: Vec3 = { x: 0, y: -1, z: 0 };
const FORWARD: Vec3 = { x: 0, y: 0, z: 1 };

const ROTATING_KINDS: Partial<Record<MovingObstacle['type'], RotatingKind>> = {
  spinner: 'spinner',
  windmill: 'windmill',
  pendulum: 'pendulum',
};

const MOVER_KINDS: Partial<Record<MovingObstacle['type'], MoverKind>> = {
  platform: 'platform',
  'sliding-wall': 'sliding-wall',
  door: 'door',
  gate: 'door',
};

const PAD_KINDS: Record<PadDescriptor['type'], PadKind> = {
  'spring-pad': 'spring',
  'boost-pad': 'boost',
  'jump-pad': 'jump',
};

/** Obstacle volumes only ever rotate around Y, so the quaternion collapses to a yaw. */
function yawOf(rotation: Quat | undefined): number {
  if (!rotation) return 0;
  const { x, y, z, w } = rotation;
  return Math.atan2(2 * (w * y + x * z), 1 - 2 * (y * y + z * z));
}

function halfExtentsOf(obstacle: ObstacleDescriptor): Vec3 {
  const scale = obstacle.transform.scale;
  return {
    x: Math.abs(obstacle.size.x * (scale?.x ?? 1)) / 2,
    y: Math.abs(obstacle.size.y * (scale?.y ?? 1)) / 2,
    z: Math.abs(obstacle.size.z * (scale?.z ?? 1)) / 2,
  };
}

/** Oriented box the force obstacles and pads test the ball against. */
export function descriptorZone(obstacle: ObstacleDescriptor): BoxZone {
  return {
    shape: 'box',
    center: { ...obstacle.transform.position },
    halfExtents: halfExtentsOf(obstacle),
    rotationY: yawOf(obstacle.transform.rotation),
  };
}

/** Axis aligned bounds used by the gameplay zones, which never rotate. */
export function descriptorBounds(obstacle: ObstacleDescriptor): ZoneBounds {
  const center = obstacle.transform.position;
  const half = halfExtentsOf(obstacle);
  return {
    min: { x: center.x - half.x, y: center.y - half.y, z: center.z - half.z },
    max: { x: center.x + half.x, y: center.y + half.y, z: center.z + half.z },
  };
}

export function isForceObstacle(obstacle: ObstacleDescriptor): obstacle is ForceObstacle {
  return obstacle.type === 'teleporter' || obstacle.type === 'fan' || obstacle.type === 'conveyor';
}

export function isPadDescriptor(obstacle: ObstacleDescriptor): obstacle is PadDescriptor {
  return obstacle.type === 'spring-pad' || obstacle.type === 'boost-pad' || obstacle.type === 'jump-pad';
}

export function isFieldObstacle(obstacle: ObstacleDescriptor): obstacle is FieldObstacle {
  return obstacle.type === 'gravity-zone' || obstacle.type === 'magnet-zone';
}

export function isHazardObstacle(obstacle: ObstacleDescriptor): obstacle is HazardObstacle {
  return (
    obstacle.type === 'water' ||
    obstacle.type === 'void' ||
    obstacle.type === 'reset-zone' ||
    obstacle.type === 'lava'
  );
}

export function isMovingObstacle(obstacle: ObstacleDescriptor): obstacle is MovingObstacle {
  return 'motion' in obstacle;
}
